{"command":"kubectl run curl-test --rm -i --restart=Never --image=busybox:1.36 --command -- sh -c 'host=$(kubectl get svc app -n default -o jsonpath='{.spec.clusterIP}');
set -o pipefail
for p in /app /app/other /app/foo; do
  echo "=== $p ===";
  curl -sS -m 5 --max-time 5 --resolve "$host:80/tcp" -o /dev/null -w "svc_code=%{http_code}\n" http://$host/$p 2>&1
  echo "exit=$?"
done"}

